mapper.select:
select e.*, p.park_name, u.user_name from enter e left join parking p on e.park_id = p.id left join user u on e.user_id = u.id
e.user_id =#{userId}
and park_name like concat('%',#{parkName},'%')
and e.enter_time >= #{startDateTime} and e.enter_time < #{endDateTime}
order by e.enter_time desc,e.id desc

select e.*, p.park_name, p.admin_id, u.user_name from enter e left join parking p on e.park_id = p.id left join user u on e.user_id = u.id
p.admin_id=#{adminId}
and e.plate_num like concat('%',#{plateNum},'%')
and park_name like concat('%',#{parkName},'%')
and flag = #{flag}
order by e.enter_time desc,e.id desc

select e.*, p.park_name, p.admin_id, u.user_name from enter e left join parking p on e.park_id = p.id left join user u on e.user_id = u.id left join admin a on p.admin_id=a.id
admin_name = #{adminName}
and e.plate_num like concat('%',#{plateNum},'%')
and park_name like concat('%',#{parkName},'%')
and flag = #{flag}
order by e.enter_time desc,e.id desc
